package main

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/davijardimn/varnqor/internal/analytics"
	"github.com/davijardimn/varnqor/internal/domain"
	"github.com/davijardimn/varnqor/internal/settings"
	"github.com/davijardimn/varnqor/internal/storage"
)

func runExploreCLI(args []string)(bool,int){filter,err:=parseExploreArgs(args);if err!=nil{fmt.Fprintln(os.Stderr,"explore:",err);return true,2};report,err:=loadExploreCLI(filter);if err!=nil{fmt.Fprintln(os.Stderr,"explore:",err);return true,1};if wantsJSON(args){printJSON(report);return true,0};fmt.Printf("VARNQOR EXPLORE · %s\n\n",exploreRangeLabel(report.Filter.RangeMinutes));fmt.Printf("Tokens       %d (%+.1f%% vs previous)\n",report.Current.Tokens.Total,report.Comparison.TokensChangePercent);fmt.Printf("Calls        %d (%+.1f%%)\n",report.Current.Calls,report.Comparison.CallsChangePercent);fmt.Printf("Sessions     %d · Projects %d\n",report.Current.Sessions,report.Current.Projects);fmt.Printf("Cache read   %.1f%% (%+.1f pts)\n",report.Current.CacheReadShare,report.Comparison.CacheChangePoints);if len(report.Projects)>0{fmt.Println("\nTOP PROJECTS");for i,item:=range report.Projects{if i>=8{break};fmt.Printf("%-28s %-8s %10d tokens %6.1f%%\n",trimWidth(item.Name,28),strings.ToUpper(item.Provider),item.Tokens.Total,item.SharePercent)}};if len(report.Sessions)>0{fmt.Println("\nHOT SESSIONS");for i,item:=range report.Sessions{if i>=8{break};fmt.Printf("%-22s %-22s %10d tokens %6.1f%%\n",trimWidth(item.Project,22),trimWidth(item.Session,22),item.Tokens.Total,item.SharePercent)}};return true,0}

func runPulseCLI(args []string)(bool,int){filter,err:=parseExploreArgs(args);if err!=nil{fmt.Fprintln(os.Stderr,"pulse:",err);return true,2};report,err:=loadExploreCLI(filter);if err!=nil{fmt.Fprintln(os.Stderr,"pulse:",err);return true,1};if wantsJSON(args){printJSON(report.Signals);return true,0};fmt.Printf("VARNQOR PULSE · %s\n\n",exploreRangeLabel(report.Filter.RangeMinutes));if len(report.Signals)==0{fmt.Println("QUIET · no enabled guardrail crossed its threshold");return true,0};for _,signal:=range report.Signals{fmt.Printf("%-6s %-22s %s\n",strings.ToUpper(signal.Severity),signal.Title,signal.Detail)};return true,0}

func runExportCLI(args []string)(bool,int){filter,err:=parseExploreArgs(args);if err!=nil{fmt.Fprintln(os.Stderr,"export:",err);return true,2};format:="json";for i,arg:=range args{if arg=="--format"&&i+1<len(args){format=strings.ToLower(args[i+1])}};report,err:=loadExploreCLI(filter);if err!=nil{fmt.Fprintln(os.Stderr,"export:",err);return true,1};if format=="json"{printJSON(report);return true,0};if format!="csv"{fmt.Fprintln(os.Stderr,"export: --format must be json or csv");return true,2};fmt.Println("timestamp,provider,project,session,model,input_tokens,output_tokens,cache_creation_tokens,cache_read_tokens,total_tokens,subagent");for _,item:=range report.Recent{fmt.Printf("%s,%s,%s,%s,%s,%d,%d,%d,%d,%d,%t\n",csvEscape(item.Timestamp.Format(time.RFC3339)),csvEscape(item.Provider),csvEscape(item.Project),csvEscape(item.Session),csvEscape(item.Model),item.Tokens.Input,item.Tokens.Output,item.Tokens.CacheCreation,item.Tokens.CacheRead,item.Tokens.Total,item.Subagent)};return true,0}

func loadExploreCLI(filter domain.ExploreFilter)(domain.ExploreReport,error){status:=loadCLIStatus();if status.UsageError!=""{return domain.ExploreReport{},errors.New(status.UsageError)};store,err:=storage.OpenDefault();if err!=nil{return domain.ExploreReport{},err};defer store.Close();report,err:=store.Explore(filter,time.Now());if err!=nil{return report,err};cfg,cfgErr:=settings.LoadDefault();if cfgErr==nil{g:=cfg.Guardrails;report.Signals=analytics.BuildPulse(report,analytics.PulsePolicy{Enabled:g.Enabled,SpikePercent:g.SpikePercent,ProjectConcentrationPercent:g.ProjectConcentrationPercent,SessionConcentrationPercent:g.SessionConcentrationPercent,CacheReadMinimumPercent:g.CacheReadMinimumPercent,MinimumTokens:g.MinimumTokens})};return report,nil}

func parseExploreArgs(args []string)(domain.ExploreFilter,error){filter:=domain.ExploreFilter{RangeMinutes:60,Limit:50};for i:=0;i<len(args);i++{switch args[i]{case"--json":case"--range":if i+1>=len(args){return filter,errors.New("--range requires a value")};i++;minutes,err:=parseExploreRange(args[i]);if err!=nil{return filter,err};filter.RangeMinutes=minutes;case"--provider":if i+1>=len(args){return filter,errors.New("--provider requires a value")};i++;filter.Provider=args[i];case"--project":if i+1>=len(args){return filter,errors.New("--project requires a value")};i++;filter.Project=args[i];case"--model":if i+1>=len(args){return filter,errors.New("--model requires a value")};i++;filter.Model=args[i];case"--limit":if i+1>=len(args){return filter,errors.New("--limit requires a value")};i++;value,err:=strconv.Atoi(args[i]);if err!=nil{return filter,errors.New("invalid --limit")};filter.Limit=value;case"--format":if i+1>=len(args){return filter,errors.New("--format requires a value")};i++;default:if strings.HasPrefix(args[i],"-"){return filter,fmt.Errorf("unknown option %q",args[i])}}};return storage.NormalizeExploreFilter(filter),nil}
func parseExploreRange(value string)(int,error){value=strings.TrimSpace(strings.ToLower(value));if strings.HasSuffix(value,"d"){days,err:=strconv.Atoi(strings.TrimSuffix(value,"d"));if err!=nil||days<=0{return 0,fmt.Errorf("invalid range %q",value)};return days*24*60,nil};if strings.HasSuffix(value,"h"){hours,err:=strconv.Atoi(strings.TrimSuffix(value,"h"));if err!=nil||hours<=0{return 0,fmt.Errorf("invalid range %q",value)};return hours*60,nil};minutes,err:=strconv.Atoi(strings.TrimSuffix(value,"m"));if err!=nil||minutes<=0{return 0,fmt.Errorf("invalid range %q",value)};return minutes,nil}
func exploreRangeLabel(minutes int)string{if minutes%(24*60)==0{return fmt.Sprintf("%dd",minutes/(24*60))};if minutes%60==0{return fmt.Sprintf("%dh",minutes/60)};return fmt.Sprintf("%dm",minutes)}
func trimWidth(value string,width int)string{r:=[]rune(value);if len(r)<=width{return value};if width<2{return string(r[:width])};return string(r[:width-1])+"…"}
func csvEscape(value string)string{if strings.ContainsAny(value,",\"\n\r"){return "\""+strings.ReplaceAll(value,"\"","\"\"")+"\""};return value}
